	warehouses := LowStockWarehouses(stock)
	report := LowStockReport(stock)
	if len(report) != len(warehouses) {
		t.Fatalf("报告 %v 与仓库列表 %v 长度不一致", report, warehouses)
	}
	for i, warehouse := range warehouses {
		want := fmt.Sprintf("%s=%d", warehouse, stock[warehouse])
		if report[i] != want {
			t.Fatalf("第 %d 条 = %q，期望 %q（仓库顺序 %v）", i, report[i], want, warehouses)
		}
	}
}

func TestLowStockReportEmpty(t *testing.T) {
	if got := LowStockReport(map[string]int{"chengdu": 99}); len(got) != 0 {
		t.Fatalf("没有低库存时报告应为空，得到 %v", got)
	}
}
